1956	+
1957	+/// Same tiny fake used by `app_router_test.dart`/`main_test.dart` — gives
1958	+/// synchronous control over both [SessionStatus] values and the
1959	+/// [statusStream] emission `ExpiryOverlayHost` subscribes to.
1960	+class _FakeSessionRepository implements SessionRepository {
1961	+  SessionStatus? _status;
1962	+  final _controller = StreamController<SessionStatus>.broadcast();
1963	+
1964	+  @override
1965	+  SessionStatus? get currentStatus => _status;
1966	+
1967	+  @override
1968	+  Stream<SessionStatus> get statusStream => _controller.stream;
1969	+
1970	+  @override
1971	+  Future<Either<Failure, Unit>> restoreSession() async => right(unit);
1972	+
1973	+  @override
1974	+  void markAuthenticated() => setStatus(SessionStatus.authenticated);
1975	+
1976	+  @override
1977	+  Future<void> dispose() => _controller.close();
1978	+
1979	+  void setStatus(SessionStatus status) {
1980	+    _status = status;
1981	+    _controller.add(status);
1982	+  }
1983	+}
1984	+
1985	+void main() {
1986	+  setUp(() {
1987	+    ConfirmationDialog.isOpen = false;
1988	+  });
1989	+
1990	+  testWidgets('an expired emission before the Navigator behind navigatorKey is '
1991	+      'mounted finds no overlay context, does not throw, and resets its '
1992	+      'one-shot guard so a later mount can still show the overlay', (
1993	+    tester,
1994	+  ) async {
1995	+    final fakeSessionRepository = _FakeSessionRepository();
1996	+    addTearDown(fakeSessionRepository.dispose);
1997	+    final router = GoRouter(
1998	+      routes: [
1999	+        GoRoute(path: '/', builder: (context, state) => const SizedBox()),
2000	+      ],
2001	+    );
2002	+    addTearDown(router.dispose);
2003	+    final navigatorKey = GlobalKey<NavigatorState>();
2004	+
2005	+    // First mount: `navigatorKey` matches nothing in this tree — no
2006	+    // `Navigator` anywhere uses it — simulating the Navigator not being
2007	+    // mounted yet when the expiry event arrives.
2008	+    await tester.pumpWidget(
2009	+      Directionality(
2010	+        textDirection: TextDirection.ltr,
2011	+        child: ExpiryOverlayHost(
2012	+          sessionRepository: fakeSessionRepository,
2013	+          router: router,
2014	+          navigatorKey: navigatorKey,
2015	+          child: const SizedBox(),
2016	+        ),
2017	+      ),
2018	+    );
2019	+
2020	+    fakeSessionRepository.setStatus(SessionStatus.expired);
2021	+    await tester.pumpAndSettle();
2022	+
2023	+    expect(tester.takeException(), isNull);
2024	+    expect(find.byType(ConfirmationDialog), findsNothing);
2025	+
2026	+    // Second pump of the *same* `ExpiryOverlayHost` (same type, no key,
2027	+    // same position — its State is preserved, not remounted): now the
2028	+    // child actually contains a `Navigator` using `navigatorKey`, so
2029	+    // `navigatorKey.currentState` resolves. Re-emitting `expired` here
2030	+    // only shows the overlay if the earlier failed attempt reset
2031	+    // `_expiryOverlayShown` back to `false` — if that guard had stayed
2032	+    // stuck `true`, this second, now-resolvable attempt would stay
2033	+    // silently dropped too.
2034	+    await tester.pumpWidget(
2035	+      Directionality(
2036	+        textDirection: TextDirection.ltr,
2037	+        child: ExpiryOverlayHost(
2038	+          sessionRepository: fakeSessionRepository,
2039	+          router: router,
2040	+          navigatorKey: navigatorKey,
2041	+          child: Navigator(
2042	+            key: navigatorKey,
2043	+            onGenerateRoute: (settings) =>
2044	+                MaterialPageRoute<void>(builder: (context) => const SizedBox()),
2045	+          ),
2046	+        ),
2047	+      ),
2048	+    );
2049	+
2050	+    fakeSessionRepository.setStatus(SessionStatus.expired);
2051	+    await tester.pumpAndSettle();
2052	+
2053	+    expect(tester.takeException(), isNull);
2054	+    expect(find.text('Sessão expirada'), findsOneWidget);
2055	+  });
2056	+}
